mapper.delete:
DELETE FROM ct_friend
WHERE user_id = #{userId}
  AND friend_user_id = #{friendUserId}

mapper.update:
UPDATE ct_friend
SET status = #{status},
    updated_at = CURRENT_TIMESTAMP,
    updated_by = #{operatorId}
WHERE user_id = #{userId}
  AND friend_user_id = #{friendUserId}
  AND is_deleted = 0

UPDATE ct_friend
SET remark = #{remark},
    updated_at = CURRENT_TIMESTAMP,
    updated_by = #{userId}
WHERE user_id = #{userId}
  AND friend_user_id = #{friendUserId}
  AND is_deleted = 0
